@startuml

class Song {
  + title : string
  + year : int
  + length : double
  + genre : string
}

class Artist {
  + name : string
  + dateOfBirth : date
  + websiteURL : string
}

abstract class User {
  + userID : int
  + name : string
  + address : string
}

class RegularUser {
  + purchasingBehavior : string
}

class BusinessUser {
  + VATNumber : string
}

class Single {
  + isSingle : boolean
}

class Hit {
  + isHit : boolean
}

class Album {
  + title : string
}

class Track {
  + trackNumber : int
}

Song "*" -- "1" Artist : belongsTo
User "1" -- "*" Song : uploads
BusinessUser "1" -- "*" Song : uploads
RegularUser "1" -- "*" Song : buys
Single --|> Song
Hit --|> Song

Album "1" *-- "1..*" Track
Track "1" -- "1" Hit
RegularUser "1" -- "*" Album : composes
RegularUser "1" -- "*" Album : receivesSuggestion
User <|-- RegularUser
User <|-- BusinessUser

@enduml

